import os
import hmac
import hashlib
import secrets
import sqlite3
import time
import re
from urllib.parse import unquote
from pathlib import PurePosixPath

SECRET_KEY = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))
BASE_DIR = '/srv/app/uploads'
DB_PATH = '/srv/app/data.db'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute('PRAGMA journal_mode=WAL')
    return conn

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        salt TEXT NOT NULL,
        is_admin INTEGER DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS tokens (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        expires_at REAL NOT NULL,
        FOREIGN KEY(user_id) REFERENCES users(id)
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp REAL NOT NULL,
        user_id INTEGER,
        action TEXT NOT NULL,
        detail TEXT
    )''')
    db.commit()
    return db

def hash_password(password, salt=None):
    if salt is None:
        salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt.encode('utf-8'), 310000)
    return h.hex(), salt

def verify_password(password, stored_hash, salt):
    h = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt.encode('utf-8'), 310000)
    return hmac.compare_digest(h.hex(), stored_hash)

def create_token(user_id):
    token = secrets.token_urlsafe(32)
    expires = time.time() + 3600
    db = get_db()
    db.execute('INSERT INTO tokens (token, user_id, expires_at) VALUES (?, ?, ?)',
               (token, user_id, expires))
    db.commit()
    return token

def validate_token(token):
    if not token or not isinstance(token, str):
        return None
    db = get_db()
    row = db.execute('SELECT user_id, expires_at FROM tokens WHERE token = ?', (token,)).fetchone()
    if not row:
        return None
    if time.time() > row[1]:
        db.execute('DELETE FROM tokens WHERE token = ?', (token,))
        db.commit()
        return None
    return row[0]

def audit(user_id, action, detail=None):
    db = get_db()
    safe_detail = detail.replace('\n', ' ').replace('\r', ' ')[:500] if detail else None
    db.execute('INSERT INTO audit_log (timestamp, user_id, action, detail) VALUES (?, ?, ?, ?)',
               (time.time(), user_id, action, safe_detail))
    db.commit()

def sanitize_filename(filename):
    """Remove dangerous characters and normalize the filename."""
    # Decode any URL encoding first
    decoded = unquote(filename)
    # Remove null bytes
    decoded = decoded.replace('\x00', '')
    # Normalize path separators
    decoded = decoded.replace('\\', '/')
    return decoded

def resolve_path(user_dir, filename):
    """Safely resolve a file path within the user's directory.

    Uses a two-phase approach:
    1. Sanitize the filename to remove dangerous characters
    2. Verify the resolved path is within bounds
    """
    sanitized = sanitize_filename(filename)

    # Phase 2: Build the path and verify containment
    # Use os.path.join for proper path construction
    candidate = os.path.normpath(os.path.join(user_dir, sanitized))

    # Security check: ensure resolved path starts with user directory
    # Normalize the base directory too for consistent comparison
    safe_base = os.path.normpath(user_dir)

    if not candidate.startswith(safe_base + os.sep) and candidate != safe_base:
        audit(None, 'path_violation', f'Blocked: {filename}')
        return None

    return candidate

def get_user_directory(user_id):
    """Get the upload directory for a specific user."""
    user_dir = os.path.join(BASE_DIR, str(user_id))
    os.makedirs(user_dir, exist_ok=True)
    return user_dir

def list_files(token, subdirectory=''):
    """List files in user's directory or subdirectory."""
    user_id = validate_token(token)
    if user_id is None:
        return {'error': 'unauthorized'}

    user_dir = get_user_directory(user_id)

    if subdirectory:
        target = resolve_path(user_dir, subdirectory)
        if target is None:
            return {'error': 'invalid path'}
    else:
        target = user_dir

    if not os.path.isdir(target):
        return {'error': 'not a directory'}

    entries = []
    for entry in os.scandir(target):
        entries.append({
            'name': entry.name,
            'is_dir': entry.is_dir(),
            'size': entry.stat().st_size if entry.is_file() else 0
        })

    audit(user_id, 'list_files', target)
    return {'files': entries}

def read_file(token, filepath):
    """Read a file from the user's upload directory."""
    user_id = validate_token(token)
    if user_id is None:
        return {'error': 'unauthorized'}

    user_dir = get_user_directory(user_id)
    resolved = resolve_path(user_dir, filepath)

    if resolved is None:
        return {'error': 'access denied'}

    if not os.path.isfile(resolved):
        return {'error': 'file not found'}

    audit(user_id, 'read_file', resolved)

    with open(resolved, 'r', encoding='utf-8', errors='replace') as f:
        content = f.read(1024 * 1024)  # 1MB limit

    return {'content': content, 'path': filepath}

def write_file(token, filepath, content):
    """Write content to a file in the user's upload directory."""
    user_id = validate_token(token)
    if user_id is None:
        return {'error': 'unauthorized'}

    if len(content) > 1024 * 1024:
        return {'error': 'content too large'}

    user_dir = get_user_directory(user_id)
    resolved = resolve_path(user_dir, filepath)

    if resolved is None:
        return {'error': 'access denied'}

    os.makedirs(os.path.dirname(resolved), exist_ok=True)

    with open(resolved, 'w', encoding='utf-8') as f:
        f.write(content)

    audit(user_id, 'write_file', resolved)
    return {'success': True, 'path': filepath}

def delete_file(token, filepath):
    """Delete a file from the user's upload directory."""
    user_id = validate_token(token)
    if user_id is None:
        return {'error': 'unauthorized'}

    user_dir = get_user_directory(user_id)
    resolved = resolve_path(user_dir, filepath)

    if resolved is None:
        return {'error': 'access denied'}

    if not os.path.exists(resolved):
        return {'error': 'file not found'}

    if os.path.isdir(resolved):
        return {'error': 'cannot delete directory'}

    os.unlink(resolved)
    audit(user_id, 'delete_file', resolved)
    return {'success': True}

def admin_read_file(token, filepath):
    """Admin endpoint to read any file within the uploads base directory."""
    user_id = validate_token(token)
    if user_id is None:
        return {'error': 'unauthorized'}

    db = get_db()
    user = db.execute('SELECT is_admin FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user or not user[0]:
        return {'error': 'forbidden'}

    # Admin can access any user's files but still within BASE_DIR
    sanitized = sanitize_filename(filepath)
    candidate = os.path.normpath(os.path.join(BASE_DIR, sanitized))
    safe_base = os.path.normpath(BASE_DIR)

    if not candidate.startswith(safe_base + os.sep) and candidate != safe_base:
        audit(user_id, 'admin_path_violation', f'Blocked: {filepath}')
        return {'error': 'access denied'}

    if not os.path.isfile(candidate):
        return {'error': 'file not found'}

    audit(user_id, 'admin_read', candidate)

    with open(candidate, 'r', encoding='utf-8', errors='replace') as f:
        content = f.read(1024 * 1024)

    return {'content': content, 'path': filepath}

def shared_file_access(token, owner_id, filepath):
    """Access another user's shared file via a special sharing mechanism.

    This endpoint allows cross-user file access for files in 'shared' subdirectories.
    The filepath is relative to the owner's shared directory.
    """
    user_id = validate_token(token)
    if user_id is None:
        return {'error': 'unauthorized'}

    # Get owner's shared directory
    owner_dir = get_user_directory(owner_id)
    shared_dir = os.path.join(owner_dir, 'shared')

    if not os.path.isdir(shared_dir):
        return {'error': 'no shared directory'}

    # Sanitize and resolve within shared directory
    sanitized = sanitize_filename(filepath)

    # Additional validation: reject obvious traversal attempts
    if '..' in sanitized:
        audit(user_id, 'traversal_attempt', f'Rejected: {filepath}')
        return {'error': 'invalid path'}

    # Build final path
    final_path = os.path.normpath(os.path.join(shared_dir, sanitized))

    # Containment check
    safe_shared = os.path.normpath(shared_dir)
    if not final_path.startswith(safe_shared + os.sep) and final_path != safe_shared:
        return {'error': 'access denied'}

    if not os.path.isfile(final_path):
        return {'error': 'file not found'}

    audit(user_id, 'shared_access', f'owner={owner_id} path={final_path}')

    with open(final_path, 'r', encoding='utf-8', errors='replace') as f:
        content = f.read(1024 * 1024)

    return {'content': content, 'path': filepath}

def handle_request(request):
    """Main request dispatcher."""
    action = request.get('action')
    token = request.get('token')

    if action == 'login':
        username = request.get('username', '')
        password = request.get('password', '')
        if not username or not password:
            return {'error': 'missing credentials'}
        db = get_db()
        user = db.execute('SELECT id, password_hash, salt FROM users WHERE username = ?',
                         (username,)).fetchone()
        if not user or not verify_password(password, user[1], user[2]):
            return {'error': 'invalid credentials'}
        token = create_token(user[0])
        audit(user[0], 'login', f'user={username}')
        return {'token': token}

    elif action == 'list':
        return list_files(token, request.get('path', ''))

    elif action == 'read':
        return read_file(token, request.get('path', ''))

    elif action == 'write':
        return write_file(token, request.get('path', ''), request.get('content', ''))

    elif action == 'delete':
        return delete_file(token, request.get('path', ''))

    elif action == 'admin_read':
        return admin_read_file(token, request.get('path', ''))

    elif action == 'shared':
        return shared_file_access(token, request.get('owner_id'), request.get('path', ''))

    return {'error': 'unknown action'}
